package in.aicon.pocket;
import android.content.Context;import android.database.sqlite.SQLiteDatabase;import org.json.*;
import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class SyncStoreTest {
 SQLiteDatabase db;SqliteSyncStore store;String subject="123456789012345678901";
 @Before public void setup()throws Exception{Context c=RuntimeEnvironment.getApplication();String name=AccountScope.databaseFor(subject);c.deleteDatabase(name);db=c.openOrCreateDatabase(name,0,null);store=new SqliteSyncStore(db,subject);}
 @After public void close(){db.close();}
 SyncModel.Record edit(String id,String payload,boolean delete)throws Exception{db.beginTransaction();try{store.localEdit(id,payload,delete);db.setTransactionSuccessful();}finally{db.endTransaction();}return store.snapshot().records.get(id);}
 @Test public void localEditAndDeleteAreAtomicAndContentFree()throws Exception{String id=UUID.randomUUID().toString();edit(id,"financial content",false);assertEquals(1,store.pending().size());SyncModel.Record dead=edit(id,null,true);assertTrue(dead.deleted);assertNull(dead.payload);assertEquals(1,store.pending().size());assertTrue(store.pending().get(0).record.deleted);try(android.database.Cursor c=db.rawQuery("SELECT body FROM cloud_outbox",null)){assertTrue(c.moveToFirst());assertFalse(c.getString(0).contains("financial content"));}try{edit(id,"revive",false);fail();}catch(IllegalStateException expected){}assertTrue(store.snapshot().records.get(id).deleted);}
 @Test public void reservationSurvivesReopenAndAcknowledgesOnlyExactOperation()throws Exception{String id=UUID.randomUUID().toString();edit(id,"a",false);SyncEngine.Pending op=store.pending().get(0);SyncEngine.Pending first=store.reserve(op.operationId,"drive_A");assertEquals("drive_A",first.fileId);assertEquals("drive_A",store.reserve(op.operationId,"drive_B").fileId);db.close();db=RuntimeEnvironment.getApplication().openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);store=new SqliteSyncStore(db,subject);assertEquals("drive_A",store.pending().get(0).fileId);store.acknowledge(op.operationId,"drive_B");assertEquals(1,store.pending().size());store.acknowledge(op.operationId,"drive_A");assertTrue(store.pending().isEmpty());assertEquals("a",store.snapshot().records.get(id).payload);}
 @Test public void accountMismatchAndUntransactionalEditAreRejected()throws Exception{try{new SqliteSyncStore(db,"987654321");fail();}catch(IllegalArgumentException expected){}try{store.localEdit(UUID.randomUUID().toString(),"unsafe",false);fail();}catch(IllegalStateException expected){}assertTrue(store.snapshot().records.isEmpty());}
 @Test public void concurrentLocalEditRejectsOldMerge()throws Exception{String id=UUID.randomUUID().toString();edit(id,"one",false);SyncEngine.Snapshot old=store.snapshot();edit(id,"two",false);assertFalse(store.commitMerge(old.revision,old.records));assertEquals("two",store.snapshot().records.get(id).payload);}
 @Test public void rollbackDoesNotLeaveOutboxOrRecord()throws Exception{db.beginTransaction();try{store.localEdit(UUID.randomUUID().toString(),"rolled back",false);}finally{db.endTransaction();}assertTrue(store.snapshot().records.isEmpty());assertTrue(store.pending().isEmpty());}
 @Test public void remoteMergeRetainsTombstonesAndRejectsRewind()throws Exception{String id=UUID.randomUUID().toString();SyncModel.Record r=edit(id,"a",false);SyncModel.Record dead=r.edit("other_device",null,true);SyncEngine.Snapshot now=store.snapshot();assertTrue(store.commitMerge(now.revision,Collections.singletonMap(id,dead)));assertTrue(store.snapshot().records.get(id).deleted);try{store.commitMerge(store.snapshot().revision,Collections.singletonMap(id,r));fail();}catch(IllegalArgumentException expected){}assertTrue(store.snapshot().records.get(id).deleted);}
 @Test public void strictJsonRejectsContentInDeletionAndFractionalClock()throws Exception{String id=UUID.randomUUID().toString();SyncModel.Record r=new SyncModel.Record(id,"a",false,Collections.singletonMap("device",1L));assertEquals("a",SyncJson.parseRecord(SyncJson.record(r)).payload);JSONObject bad=new JSONObject(SyncJson.record(r));bad.put("deleted",true);try{SyncJson.parseRecord(bad.toString());fail();}catch(IllegalArgumentException expected){}bad=new JSONObject(SyncJson.record(r));bad.getJSONObject("clock").put("device",1.5);try{SyncJson.parseRecord(bad.toString());fail();}catch(IllegalArgumentException expected){}}
 @Test public void shortenedIdsAndInvalidCatalogNumbersAreRejected()throws Exception{try{new SyncModel.Record("1-1-1-1-1","data",false,Collections.emptyMap());fail();}catch(IllegalArgumentException expected){}JSONObject c=new JSONObject().put("uuid",UUID.randomUUID().toString()).put("type","category").put("name","Food").put("icon",1.5).put("color","System");try{CatalogStore.validateExport(new JSONArray().put(c));fail();}catch(IllegalArgumentException expected){}Map<String,Long> clocks=new HashMap<>();for(int n=0;n<257;n++)clocks.put("device"+n,1L);try{new SyncModel.Record(UUID.randomUUID().toString(),"data",false,clocks);fail();}catch(IllegalArgumentException expected){}}

}
